+    return [acao, await medida(acao, () => outras(acao, params))];
+  }));
+  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
+  medir('tela_dados', ms);
+  return [200, Object.fromEntries(pares), ms];
+}
